def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    try:
        seconds = value.total_seconds()
    except AttributeError:
        return None
    return int(seconds) if seconds.is_integer() else seconds

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    # Convert a datetime.time instance to its ISO 8601 string representation
    return value.isoformat()

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    if hasattr(self, "_data") and isinstance(self._data, dict):
        return list(self._data.keys())
    return []

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Retrieve the mapping of available handlers from the class.
    handlers = getattr(cls, "PROTOCOL_HANDLERS", {})
    if not isinstance(handlers, dict):
        # If the attribute exists but isn't a dict, treat it as empty.
        handlers = {}

    # If a specific version is requested, validate and return
    # either the single handler or an empty dict.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        if protocol_version in handlers:
            return {protocol_version: handlers[protocol_version]}
        return {}

    # No specific version requested – return all available handlers.
    return dict(handlers)

def index(self, key):
    """
    Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Try a direct lookup map if one exists
    try:
        return self.index_lookup[key]
    except (AttributeError, KeyError):
        pass
    # Fallback to searching in lists
    try:
        return self._keys.index(key)
    except (AttributeError, ValueError):
        pass
    try:
        return self._index.index(key)
    except (AttributeError, ValueError) as exc:
        raise KeyError(f'Key {key!r} not found') from exc

def values(self, *keys):
        """
        Return the values of the record, optionally filtering to
        include only certain values by index or key.

        :param keys: indexes or keys of the items to include; if none
                     are provided, all values will be included
        :return: list of values
        :rtype: list
        """
        items = getattr(self, "_items", None)
        if items is None:
            return []

        # If no keys are supplied, return all values
        if not keys:
            if isinstance(items, dict):
                return list(items.values())
            else:
                # list/tuple/etc.
                return list(items)

        result = []
        for k in keys:
            if isinstance(items, dict):
                if k in items:
                    result.append(items[k])
            else:
                # Assume a sequence and use integer index
                try:
                    result.append(items[k])
                except (IndexError, TypeError):
                    continue
        return result

def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError('not enough data to pop')
    b = self.data[-2:]
    del self.data[-2:]
    return int.from_bytes(b, byteorder='big')

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Build the DISCARD message payload
    msg = {"type": "DISCARD", "n": n, "qid": qid}
    if dehydration_hooks:
        msg["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks:
        msg["hydration_hooks"] = hydration_hooks

    # Emit the message to the output queue
    try:
        # Prefer the explicit queue attribute if it exists
        queue = getattr(self, "_output_queue", None)
        if queue is None:
            queue = getattr(self, "output_queue", None)
        if queue is None:
            # Fallback: try a generic send method
            if hasattr(self, "send"):
                queue = self.send
        if queue is None:
            raise AttributeError("No output queue or send method available")
        if hasattr(queue, "append"):
            queue.append(msg)
        elif hasattr(queue, "put"):
            queue.put(msg)
        elif callable(queue):
            queue(msg)
        else:
            raise TypeError("Unsupported queue type")
    except Exception as exc:
        raise RuntimeError(f"Failed to enqueue DISCARD message: {exc}") from exc

    # Return a Response object that allows callers to attach custom handlers.
    # If a Response class is available on the instance, use it; otherwise
    # fallback to a simple lambda that triggers handlers immediately.
    ResponseCls = getattr(self, "Response", None)
    if ResponseCls:
        return ResponseCls(self, msg, **handlers)
    # Fallback lightweight response
    class SimpleResponse:
        def __init__(self, callback, message):
            self.callback = callback
            self.message = message
            self._run_handlers()

        def _run_handlers(self):
            for name, func in handlers.items():
                if callable(func):
                    try:
                        func(self.message)
                    except Exception as exc:
                        # swallow exceptions from handlers to avoid breaking flow
                        pass

        def wait(self, timeout=None):
            # no-op, just placeholder
            return None

    return SimpleResponse(self, msg)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """Append a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration
        function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Validate mode
    if mode is not None and mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")
    # Prepare payload
    payload = {}
    if mode is not None:
        payload["mode"] = mode
    if bookmarks:
        payload["bookmarks"] = list(bookmarks)
    if metadata:
        payload["metadata"] = metadata
    if timeout is not None:
        payload["timeout"] = float(timeout)
    if db:
        payload["db"] = db
    if imp_user:
        payload["imp_user"] = imp_user
    # Update hooks if given
    if dehydration_hooks:
        if not hasattr(self, "dehydration_hooks"):
            self.dehydration_hooks = {}
        self.dehydration_hooks.update(dehydration_hooks)
    if hydration_hooks:
        if not hasattr(self, "hydration_hooks"):
            self.hydration_hooks = {}
        self.hydration_hooks.update(hydration_hooks)
    # Append the BEGIN message to the outgoing queue
    self._outbound.append(("BEGIN", payload))
    # Return a Response object; the handlers are forwarded
    return Response(self, **handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Build the namespace for the new class
    namespace = {
        # Store the SRID mapping on the class for later reference
        "srid_map": srid_map,
    }

    # If `fields` is a sequence of strings or (name, type) tuples, construct
    # annotations accordingly.  Unsupported types will raise a TypeError.
    annotations = {}
    for field in fields:
        if isinstance(field, str):
            # If only a name is provided, default to 'typing.Any'
            annotations[field] = "typing.Any"
        else:
            try:
                # Expect a tuple (name, type) or (name, type, default)
                name, t = field[0], field[1]
            except Exception as exc:
                raise TypeError(f"Invalid field specification: {field!r}") from exc
            annotations[name] = t
    namespace["__annotations__"] = annotations

    # Dynamically create the class that inherits from `Point`
    # (Assumes `Point` is defined in the same module or imported beforehand.)
    # Using `type` because we don’t need static metaclasses or special
    # initialization logic.
    new_cls = type(name, (Point,), namespace)
    return new_cls

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split(".")
    version_parts: list[int] = []
    for part in parts:
        num_str = ""
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            version_parts.append(int(num_str))
    return tuple(version_parts)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            key += tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(v) for v in args)
            if kwargs:
                key += tuple(type(v) for _, v in sorted(kwargs.items()))
        return key

    def decorator(func):
        cache = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            now = timer()
            if key in cache:
                value, expire = cache.pop(key)
                if now < expire:
                    cache[key] = (value, expire)
                    return value
            result = func(*args, **kwargs)
            expire_time = now + ttl
            if maxsize and len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[key] = (result, expire_time)
            return result

        def cache_clear():
            cache.clear()

        wrapper.clear = cache_clear
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            # stable ordering of keyword arguments
            kw_tuple = tuple(sorted(kwargs.items()))
            key += kw_tuple
        if typed:
            # include type information to separate distinct types
            processed = []
            for v in key:
                if isinstance(v, type):
                    processed.append(v)
                else:
                    processed.append((type(v), v))
            return tuple(processed)
        return key

    def decorating_function(user_function):
        if maxsize <= 0:
            # no caching
            return user_function

        cache = {}
        freq = {}

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                freq[key] = freq.get(key, 0) + 1
                return cache[key]
            result = user_function(*args, **kwargs)
            if len(cache) >= maxsize:
                # Find key with minimal frequency
                min_freq = None
                key_to_remove = None
                for k in cache:
                    f = freq.get(k, 0)
                    if min_freq is None or f < min_freq:
                        min_freq = f
                        key_to_remove = k
                if key_to_remove is not None:
                    del cache[key_to_remove]
                    del freq[key_to_remove]
            cache[key] = result
            freq[key] = 1
            return result

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        first_key = next(iter(self))
        value = dict.pop(self, first_key)
        return (first_key, value)
    except StopIteration:
        raise KeyError('dictionary is empty')

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    return self._value.setdefault(key, default)

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
