def _reset_logging(cls):
    """
    Reset
    """
    logger = getattr(cls, 'logger', None)
    if logger:
        for h in logger.handlers[:]:
            logger.removeHandler(h)
    root = logging.getLogger()
    for h in root.handlers[:]:
        root.removeHandler(h)
    root.setLevel(logging.WARNING)

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    result = {}
    # Determine which classes to inspect
    classes = (self,) if not all else (self,) + self.__bases__
    for cls in classes:
        for name, obj in cls.__dict__.items():
            # Skip private or special attributes
            if name.startswith('_'):
                continue
            # Many interface attributes are descriptor objects that
            # have a `description` attribute (e.g., zope.interface.Attribute).
            if hasattr(obj, 'description'):
                result[name] = obj.description
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names from the class and its bases, excluding private
    # and internal members, and optionally including callables.
    attribute_names = set()
    for cls in self.__class__.__mro__:
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                # Skip private and special attributes
                continue
            is_callable = callable(value)
            if all or not is_callable:
                attribute_names.add(name)
    # Return a sorted list for consistent ordering
    return sorted(attribute_names)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    import numpy as np
    errors = getattr(self, 'errors', {})
    err_arr = errors.get(coord_name)
    if err_arr is None:
        return []
    err_arr = np.asarray(err_arr)
    mask = np.isfinite(err_arr) & (err_arr != 0)
    return np.where(mask)[0].tolist()

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is already a single FillRequest instance, it is valid.
    if isinstance(seq, FillRequest):
        return True

    # A Source sequence should not be considered a FillRequestSeq.
    if isinstance(seq, Source):
        return False

    # Try to iterate over seq; if it is not iterable, it cannot be a sequence.
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    # Strings (and bytes) are technically iterable but should not be
    # treated as sequences for this purpose.
    if isinstance(seq, (str, bytes)):
        return False

    # Check if at least one element of the sequence is a FillRequest.
    for element in iterator:
        if isinstance(element, FillRequest):
            return True

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return callable(getattr(obj, "fill", None)) and callable(getattr(obj, "request", None))

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return (
        hasattr(obj, 'fill') and callable(getattr(obj, 'fill'))
        and hasattr(obj, 'compute') and callable(getattr(obj, 'compute'))
    )

def validate_key(key):
