        raise ValidationError(f"No regex pattern found for key {key}")
    if not re.fullmatch(pattern, key):
        raise ValidationError(f"Key '{key}' does not conform to the required pattern.")

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """
    Recursively update a list-structured ``last_applied_manifest`` using a
    matching ``observer_schema`` and ``response``.  Missing entries in
    ``last_applied_manifest`` are filled in from ``response``.
    """
    # Ensure we iterate over the shortest length of response and schema
    for idx, resp_value in enumerate(response):
        if idx >= len(observer_schema):
            break
        schema_item = observer_schema[idx]

        # If the schema is simply a scalar type (represented as a string)
        if isinstance(schema_item, str):
            if len(last_applied_manifest) <= idx:
                # Extend the list to fit the new item
                last_applied_manifest.append(resp_value)
            elif last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = resp_value
            continue

        # If the schema describes a nested structure
        if isinstance(schema_item, dict):
            field_name = schema_item.get('name')
            if field_name is None:
                # No explicit name; treat as a scalar placed at the index
                if len(last_applied_manifest) <= idx:
                    last_applied_manifest.append(resp_value)
                else:
                    last_applied_manifest[idx] = resp_value
                continue

            # Ensure a place exists for this field in the manifest
            if field_name not in last_applied_manifest:
                last_applied_manifest[field_name] = {}

            sub_manifest = last

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for field, sub_schema in observer_schema.items():
        if field not in response:
            raise KeyError(
                f"Observed field {field!r} not present in Kubernetes response"
            )
        # If the field has not yet been populated, set its value directly
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        # If the field is a nested mapping, recurse to populate nested fields
        if isinstance(sub_schema, dict) and isinstance(response[field], dict):
            # Ensure the nested structure exists in the manifest
            if not isinstance(last_applied_manifest[field], dict):
                last_applied_manifest[field] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field], sub_schema, response[field]
            )
    return last_applied_manifest

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Ensure the base path exists and is a directory
        if not isinstance(path, (str, bytes)):
            return False
        if not os.path.exists(path) or not os.path.isdir(path):
            return False

        # Validate typical OCFL object structure
        ocfl_marker = os.path.join(path, '.ocfl-root')
        object_meta = os.path.join(path, 'object.json')
        commits_dir = os.path.join(path, 'commits')

        if not os.path.exists(ocfl_marker):
            return False
        if not os.path.exists(object_meta):
            return False
        if not os.path.isdir(commits_dir):
            return False

        # Additional basic checks could be added here (e.g., commit IDs format)
        return True
    except Exception:
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    return f"{prefix}{self.status}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # Retrieve the log container, if it exists.
    log = getattr(self, "_validation_log", None)
    if not log:
        return ''
    # Build a list of prefixed lines.
    lines = [f"{prefix}{str(msg)}" for msg in log]
    # Join them into a single string with newline separators.
    return "\n".join(lines)

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Optionally extract spec version from the 'type' field
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val is not None:
            try:
                # Assume mapping from type string to spec version is available
                self.spec_version = self._type_to_version[type_val]
            except KeyError:
                # If type is not recognized, fall back to the default spec_version
                pass

    # Validate each field defined in the schema
    for field_name, field_spec in self.spec_fields.items():
        value = inventory.get(field_name)
        field_spec.validate(value, field_name)

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict of filenames to digests")
    # Find any files whose digest is not in the used set
    missing_files = [fname for fname, digest in manifest_files.items()
                     if digest not in digests_used]
    if missing_files:
        raise ValueError("Missing digests for files: " + ", ".join(missing_files))
    # Find any digests that are used but not listed in the manifest
    unused_digests = [d for d in digests_used if d not in manifest_files.values()]
    if unused_digests:
        if hasattr(self, "logger"):
            self.logger.warn("Used digests not present in manifest: " +
                             ", ".join(unused_digests))
        else:
            print("Warning: Used digests not present in manifest:",
                  ", ".join(unused_digests))

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to convert a version string to a sortable key.
    def _ver_key(v):
        """Convert a version string into a tuple that sorts like a semantic version."""
        parts = []
        for part in v.replace("v", "").split("."):
            try:
                parts.append(int(part))
            except ValueError:
                parts.append(part)
        return tuple(parts)

    # Determine how to iterate over the inventory.
    if hasattr(inventory, "get_versions") and callable(inventory.get_versions):
        versions = list(inventory.get_versions())
    else:
        # Assume a mapping from version -> mapping of logical_path -> files
        versions = list(inventory.keys())

    # Sort the versions in natural order.
    versions = sorted(versions, key=_ver_key)

    # Find the index of the requested version.
    try:
        start_index = versions.index(version)
    except ValueError:
        raise ValueError(f"Version {version!r} not found in the inventory")

    result = {}

    # Iterate over the requested version and all later versions.
    for ver in versions[start_index:]:
        # Retrieve the mapping for this version.
        if hasattr(inventory, "get_file_map") and callable(inventory.get_file_map):
            mapping = inventory.get_file_map(ver) or {}
        else:
            mapping = inventory.get(ver, {})

        # Normalise mapping to a dict of logical_path -> iterable of files.
        for logical_path, files in mapping.items():
            if not isinstance(files, (list, tuple, set)):
                files = [files]
            result.setdefault(logical_path, set()).update(files)

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'file' not in fixity:
        raise ValueError("Missing 'file' key in fixity block")
    file_block = fixity['file']
    if not isinstance(file_block, dict):
        raise ValueError("'file' block must be a dictionary")
    for path, details in file_block.items():
        if path not in manifest_files:
            raise ValueError("File '%s' referenced in fixity but not present in manifest" % path)
        if not isinstance(details, dict):
            raise ValueError("Fixity details for file '%s' must be a dictionary" % path)
        if 'hash' not in details:
            raise ValueError("Missing 'hash' for file '%s' in fixity block" % path)
        if not isinstance(details['hash'], str):
            raise ValueError("Hash for file '%s' must be a string" % path)
    return True

def files_list(path):
    """Return the files in `path`"""
    # If path points to a file, return it in a list
    if os.path.isfile(path):
        return [path]
    # If path points to a directory, list all its file contents
    if os.path.isdir(path):
        return [os.path.join(path, f) for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f))]
    # Path does neither exist as a file nor a directory
    return []

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        filename

    Returns
    -------
    dict
    """
    package_info = {}
    try:
        with open(file_path, 'r', encoding='utf-8') as fp:
            # Read a small portion of the file to speed up detection
            snippet = fp.read(2048).lower()
        if '<rendition' in snippet:
            pkg_type = 'rendition'
        elif '<asset' in snippet:
            pkg_type = 'asset'
        else:
            pkg_type = 'unknown'
        package_info[prefix] = {'type': pkg_type, 'path': file_path}
    except (IOError, OSError) as exc:
        package_info[prefix] = {'type': 'error', 'path': file_path, 'error': str(exc)}
    return package_info

def add_rendition(self, lang, file_path):
    """{
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }"""
    base, ext = os.path.splitext(os.path.basename(file_path))
    original_file = base + ext
    rendition_file = f"{base}-{lang}{ext}"
    mapping = {"original": original_file, lang: rendition_file}
    if not hasattr(self, "_renditions"):
        self._renditions = {}
    self._renditions.update(mapping)
    return mapping

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Define the possible extensions for this asset
    extensions = ['.tiff', '.jpg', '.png']
    asset_files = {}

    # Build the full path for each possible file and verify its existence
    for ext in extensions:
        filename = f"{basename}{ext}"
        full_path = os.path.join(file_path, filename)
        if os.path.exists(full_path):
            asset_files[filename] = full_path
        else:
            logger.debug(f"Asset file not found: {full_path}")

    return asset_files

def fix_namespace_prefix_w(content):
    """Convert texts whose pattern is `w:st="` to `w-st="`."""
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
        except Exception:
            continue
        if matches:
            return matches[0]
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    import pprint
    if debug:
        return f'{pprint.pformat(self, indent=indent)} (id={id(self)})'
    return pprint.pformat(self, indent=indent)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        mod = __import__(__package__ or __name__, fromlist=['__version__'])
        return getattr(mod, "__version__", "unknown")
    except Exception:
        return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == 'html':
        return ''.join(f'<p>{p}</p>' for p in pieces)
    elif style in ('markdown', 'md'):
        return '\n\n'.join(pieces)
    elif style == 'json':
        import json
        return json.dumps(pieces)
    else:
        return '\n'.join(pieces)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if any(part == '+' for part in pieces):
        return '.'
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Ensure commands is a list of arguments
    if isinstance(commands, (list, tuple)):
        base_cmd = list(commands)
    else:
        base_cmd = [commands]

    # Append args if provided
    if args:
        if isinstance(args, (list, tuple)):
            full_cmd = base_cmd + list(args)
        else:
            full_cmd = base_cmd + [args]
    else:
        full_cmd = base_cmd

    # Optional verbose output
    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Handle stderr redirection
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=True
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
        raise RuntimeError(msg) from e

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    for obj in self._get_all_objects():
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                self._validate_object(obj)
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for {obj}: {e}")

        if check_digests:
            try:
                expected = self._get_expected_digest(obj)
                actual = self._get_actual_digest(obj)
                if expected != actual:
                    is_valid = False
                    if show_warnings:
                        print(f"Digest mismatch for {obj}: expected {expected}, got {actual}")
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Digest check error for {obj}: {e}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return str(version)
    if not version.isdigit():
        return version
    width = len(version)
    try:
        new_num = int(version) + 1
    except Exception:
        return version
    return f"{new_num:0{width}d}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # If no bug IDs are provided, nothing needs to be amended.
    if not bug_ids:
        return

    # Flatten a single bug ID into a string or convert a list/tuple into a comma‑separated string.
    if isinstance(bug_ids, (list, tuple)):
        ids_str = ','.join(str(bug_id) for bug_id in bug_ids)
    else:
        ids_str = str(bug_ids)

    # Bugzilla expects the list of IDs under the key 'ids'.
    params['ids'] = ids_str

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two mapping node value lists
    def _merge_mapping_lists(list1, list2):
        merged = {}
        order = []
        for key_node, val_node in list1:
            key_val = getattr(key_node, 'value', None)
            if key_val not in merged:
                merged[key_val] = (key_node, val_node)
                order.append(key_val)
        for key_node, val_node in list2:
            key_val = getattr(key_node, 'value', None)
            if key_val in merged:
                old_key_node, old_val_node = merged[key_val]
                if getattr(old_val_node, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(val_node, 'tag', None) == 'tag:yaml.org,2002:map':
                    # Recursively merge mapping nodes
                    merged_list = _merge_mapping_lists(old_val_node.value, val_node.value)
                    merged[key_val] = (old_key_node, type(old_val_node)(old_val_node.tag, merged_list))
                else:
                    # Override with new value (last wins)
                    merged[key_val] = (old_key_node, val_node)
            else:
                merged[key_val] = (key_node, val_node)
                order.append(key_val)
        return [(merged[k][0], merged[k][1]) for k in order]

    # Main processing
    merged_map = {}
    order = []
    for key_node, val_node in nodes:
        key_val = getattr(key_node, 'value', None)
        if key_val in merged_map:
            existing_key_node, existing_val_node = merged_map[key_val]
            if getattr(existing_val_node, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(val_node, 'tag', None) == 'tag:yaml.org,2002:map':
                merged_list = _merge_mapping_lists(existing_val_node.value, val_node.value)
                merged_map[key_val] = (existing_key_node, type(existing_val_node)(existing_val_node.tag, merged_list))
            else:
                merged_map[key_val] = (existing_key_node, val_node)
        else:
            merged_map[key_val] = (key_node, val_node)
            order.append(key_val)
    return [(merged_map[k][0], merged_map[k][1]) for k in order]

def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance.
    '''
    import argparse
    parser = argparse.ArgumentParser(description='Parse script arguments.')
    # If additional arguments are desired, they can be added here, e.g.:
    # parser.add_argument('-v', '--verbose', action='store_true', help='Enable verbose output.')
    if arguments:
        return parser.parse_args(arguments)
    else:
        return parser.parse_args()

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string.
    """
    flags = []
    for action in parser._actions:
        # Only consider optional arguments that have option strings
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
        """
        Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
        instance, give each requested action's subparser a shot at parsing all arguments. This allows
        common arguments like "--repository" to be shared across multiple subparsers.

        Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
        arguments, a list of remaining arguments not claimed by any subparser).
        """
        if not subparsers:
            return {}, list(unparsed_arguments)

        parsed = {}
        remaining_sets = None

        for name, parser in subparsers.items():
            namespace, remaining = parser.parse_known_args(list(unparsed_arguments))
            parsed[name] = namespace
            if remaining_sets is None:
                remaining_sets = set(remaining)
            else:
                remaining_sets &= set(remaining)

        remaining_args = list(remaining_sets) if remaining_sets is not None else []
        return parsed, remaining_args

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    total = {}
    for d in dicts:
        for k, v in d.items():
            total[k] = total.get(k, 0) + v
    return total

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url or not url_args:
        return url

    import re
    import urllib.parse

    # Find placeholders within curly braces, e.g. {id}
    pattern = re.compile(r'{([^{}]+)}')

    def _replace(match):
        key = match.group(1)
        if key in url_args:
            # Ensure the value is string and URL‑encoded for a path segment
            return urllib.parse.quote(str(url_args[key]), safe='')
        return match.group(0)  # leave unchanged if no value provided

    return pattern.sub(_replace, url)

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if stripped == '':
            return True
        if stripped.lower() in ('none', 'null', 'nan'):
            return True
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    # Iterate over all actions registered in the parser.  Only actions that
    # have option strings (i.e., flags such as "-v" or "--verbose") are
    # considered.  Positional arguments have an empty `option_strings`
    # list and are ignored.
    for action in parser._actions:
        if action.option_strings:
            for opt in action.option_strings:
                if opt not in flags:
                    flags.append(opt)
    return " ".join(flags)

def int_to_string(number: int, alphabet: list, padding: int | None = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base < 2:
        raise ValueError("alphabet must contain at least two distinct symbols")
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            n, r = divmod(n, base)
            digits.append(alphabet[r])
        digits.reverse()
    if padding is not None and padding > 0:
        pad_len = max(0, padding - len(digits))
        if pad_len:
            digits = [alphabet[0]] * pad_len + digits
    return "".join(digits)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    return str(value).replace('.', str(arg))

def subclasses(cls):
        """Return all subclasses of a class, recursively"""
        seen = set()
        queue = set([cls])

        while queue:
            c = queue.pop()
            seen.add(c)

            sc = c.__subclasses__()
            for subc in sc:
                if subc not in seen:
                    queue.add(subc)

        seen.remove(cls)
        return seen

def unquote(name):
    """Remove quote from the given name."""
    if len(name) > 1:
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1].replace('\\"', '"').replace('\\\\', '\\')
        if name.startswith('<') and name.endswith('>'):
            return name[1:-1]
    return name

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    # Treat "always" in a case‑insensitive manner
    if isinstance(frequency, str) and frequency.strip().lower() == "always":
        return None

    # Ensure we are working with a string for parsing
    freq_str = str(frequency).strip()
    import re
    # Regex to capture one or more digits followed by optional whitespace and letters
    m = re.match(r'^(\d+)\s*([a-zA-Z]+)$', freq_str)
    if not m:
        raise ValueError(f"Invalid frequency format: {frequency!r}")

    value = int(m.group(1))
    unit = m.group(2).lower()

    # Map the unit to a timedelta keyword argument
    if unit in ("second", "seconds"):
        return datetime.timedelta(seconds=value)
    if unit in ("minute", "minutes"):
        return datetime.timedelta(minutes=value)
    if unit in ("hour", "hours"):
        return datetime.timedelta(hours=value)
    if unit in ("day", "days"):
        return datetime.timedelta(days=value)
    if unit in ("week", "weeks"):
        return datetime.timedelta(weeks=value)
    if unit in ("month", "months"):
        # Approximating a month as 30 days
        return datetime.timedelta(days=30 * value)
    if unit in ("year", "years"):
        # Approximating a year as 365 days
        return datetime.timedelta(days=365 * value)

    raise ValueError(f"Unknown time unit: {unit!r}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Short-circuit for the literal name "localhost".
    if host == "localhost":
        return True

    try:
        # Resolve the host to get address information.
        addrinfo = socket.getaddrinfo(host, None, 0, socket.SOCK_STREAM)
    except socket.gaierror:
        # If the hostname cannot be resolved, it cannot be localhost.
        return False

    for family, _, _, _, sockaddr in addrinfo:
        if family == socket.AF_INET:
            ip, _ = sockaddr
            # Single host IP :: 127.0.0.1 or any IP in the 127.0.0.0/8 range.
            if ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip, _, _, _ = sockaddr
            # IPv6 loopback address.
            if ip == "::1":
                return True

    return False

def _resolve_string(matcher):
    '''Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    name = getattr(matcher, 'name', None)
    if not isinstance(name, str):
        raise TypeError('matcher.name must be a string')
    default = getattr(matcher, 'default', None)
    if name not in os.environ:
        if default is None:
            raise EnvironmentError(f"Environment variable {name} not found and no default provided")
        return default
    return os.environ[name]

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    if isinstance(pattern, re.Pattern):
        return pattern
    raise TypeError("Invalid regex type: %r" % (pattern,))

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
