            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else subprocess.DEVNULL,
            text=True,
            check=True if hide_stderr else False
        )
    except subprocess.CalledProcessError as e:
        # If hide_stderr is False, capture stderr; else it goes to DevNull
        error_output = e.stderr if e.stderr is not None else ''
        raise RuntimeError(f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}: {error_output}") from e

    # Return completed process-like object or dict with stdout, stderr, returncode
    return {
        'stdout': result.stdout,
        'stderr': result.stderr,
        'returncode': result.returncode
    }

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        addr = ipaddress.ip_address(target)
    except ValueError:
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumped = yaml.safe_dump(obj)
    else:
        dumped = yaml.safe_dump(obj, Dumper=dumper)
    # Ensure unicode string on Python 2
    if isinstance(dumped, bytes):
        try:
            dumped = dumped.decode('utf-8')
        except Exception:
            pass
    return dumped

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import logging
    import yaml
    import toml

    configs = {}
    error_records = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()

            # Determine parser based on file extension
            if fname.lower().endswith('.json'):
                parsed = json.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                parsed = yaml.safe_load(raw)
            elif fname.lower().endswith('.toml'):
                parsed = toml.loads(raw)
            else:
                # Try JSON first, then YAML, then fail
                try:
                    parsed = json.loads(raw)
                except Exception:
                    try:
                        parsed = yaml.safe_load(raw)
                    except Exception:
                        raise ValueError("Unsupported configuration format")

            # Apply overrides if provided
            if overrides:
                for key, value in overrides.items():
                    parsed[key] = value

            # Resolve environment variables if requested
            if resolve_env:
                def _resolve(val):
                    if isinstance(val, str):
                        return os.path.expandvars(val)
                    if isinstance(val, dict):
                        return {k: _resolve(v) for k, v in val.items()}
                    if isinstance(val, list):
                        return [_resolve(v) for v in val]
                    return val

                parsed = _resolve(parsed)

            configs[fname] = parsed

        except Exception as exc:
            record = logging.LogRecord(
                name="load_config",
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Error parsing configuration file '{fname}': {exc}",
                args=None,
                exc_info=None
            )
            error_records.append(record)

    return configs, error_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple or None")

    handlers = {}
    registry = getattr(cls, "_bolt_protocol_handlers", {})

    if protocol_version is None:
        # Return all supported handlers
        for ver, handler in registry.items():
            if isinstance(ver, tuple):
                handlers[ver] = handler
    else:
        # Return the handler for the requested version if it exists
        handler = registry.get(protocol_version)
        if handler is not None:
            handlers[protocol_version] = handler

    return handlers

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq itself is a recognised sequence type, use it directly
    if isinstance(seq, (list, tuple, set, str, bytes)):
        return seq, type(seq)
    # Otherwise try to convert to a list; if that fails, wrap as single element
    try:
        seq = list(seq)
    except Exception:
        seq = [seq]
    return seq, type(seq)

