def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass was supplied, use it
    if explicit_mc is not None:
        return explicit_mc

    # Default when no bases
    if not bases:
        return type

    # Start with the metaclass of the first base
    candidate = type(bases[0])

    # Compare against the rest of the bases
    for base in bases[1:]:
        meta = type(base)
        if meta is candidate:
            continue
        try:
            # If the new metaclass is a subclass of the current candidate,
            # it is the more derived one.
            if issubclass(meta, candidate):
                candidate = meta
            # If neither is a subclass of the other, no clear ordering.
            elif not issubclass(candidate, meta):
                raise TypeError(
                    "metaclass conflict: {} and {}".format(meta, candidate)
                )
        except TypeError:
            # Re-raise metaclass conflicts with the original exception
            raise

    return candidate

def pop(self, key, default=__marker):
    """ D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if default is __marker:
        return super().pop(key)
    return super().pop(key, default)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('dictionary is empty')
    # Identify the key with the lowest usage count
    try:
        min_key = min(self._freq, key=lambda k: self._freq[k])
    except KeyError:
        raise KeyError('dictionary is empty')
    # Retrieve the value before deletion
    value = super().__getitem__(min_key)
    # Delete the key from the main dictionary and frequency map
    super().__delitem__(min_key)
    self._freq.pop(min_key, None)
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self._store:
        raise KeyError('dict is empty')
    return self._store.popitem(last=False)

def popitem(self):
        """Remove and return the `(key, value)` pair most recently used."""
        try:
            # Pop the most recent item using OrderedDict's popitem.
            return super().popitem(last=True)
        except KeyError:
            # If the dictionary is empty, raise a KeyError.
            raise KeyError('dict is empty')

