@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")

        if isinstance(spec_content, str):
            try:
                data = yaml.safe_load(spec_content)
            except Exception as e:
                raise IRValidatorException(f"Failed to parse YAML: {e}")
        elif isinstance(spec_content, dict):
            data = spec_content
        else:
            raise IRValidatorException("spec_content must be a string or dictionary")

        if not isinstance(data, dict):
            raise IRValidatorException("YAML content is not a mapping")

        required = getattr(cls, 'REQUIRED_FIELDS', [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(f"Missing mandatory fields: {', '.join(missing)}")

        return data

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise ValueError("yaml_file must be provided")

    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except Exception as e:
        raise IRValidatorException(
            f"Error loading YAML file {yaml_file}: {e}"
        ) from e

    # Determine required fields; prefer a class attribute, otherwise an empty list
    required_fields = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required_fields if field not in data]

    if missing:
        raise IRValidatorException(
            f"Missing mandatory fields in {yaml_file}: {', '.join(missing)}"
        )

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(group):
        if isinstance(group, dict):
            if 'include' in group:
                inc_path = group.pop('include')
                inc_dict = self._load_parser_dict(inc_path)
                group.update(inc_dict)
            for k, v in list(group.items()):
                _resolve(v)
        elif isinstance(group, list):
            for item in group:
                _resolve(item)

    for key, val in list(parser_dict.items()):
        _resolve(val)

    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    if hasattr(self, "build_defaults"):
        defaults = self.build_defaults()
    if hasattr(self, "spec"):
        spec = self.spec
        if isinstance(spec, dict):
            defaults.update(spec)
        else:
            for name in dir(spec):
                if name.startswith("_"):
                    continue
                value = getattr(spec, name)
                if not callable(value):
                    defaults[name] = value
    return defaults

