def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the dictionary containing all command options
    command_opts = getattr(self, 'options', {})
    if not isinstance(command_opts, dict):
        return None
    # Narrow down to the specific command's options dictionary
    option_specs = command_opts.get(command_name)
    if not isinstance(option_specs, dict):
        return None
    # Return the specification for the requested argument name
    return option_specs.get(argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    missing = [name for name in getattr(self, 'required_args', []) if args.get(name) is None]
    if missing:
        raise InvalidArgumentError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    matched = []
    for opt in options_spec:
        condition = opt.get('required_when')
        if not condition:
            continue
        # If condition is a string, evaluate it in a safe context
        if isinstance(condition, str):
            try:
                if eval(condition, {}, {'args': args, 'command_name': command_name}):
                    matched.append(opt['name'])
                    continue
            except Exception:
                # ignore any errors in evaluating the condition
                pass
        # If condition is callable, call it with command_name and args
        if callable(condition):
            try:
                if condition(command_name, args):
                    matched.append(opt['name'])
                    continue
            except Exception:
                pass
        # If condition is a dict, check for expected keys
        if isinstance(condition, dict):
            try:
                # Example: {'command_name': 'foo'} or similar
                if condition.get('command_name') == command_name:
                    matched.append(opt['name'])
                    continue
            except Exception:
                pass
    return matched

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Iterate over all supplied arguments
    for argname, argattrs in args.items():
        # Skip if the argument value is not a mapping
        if not isinstance(argattrs, dict):
            continue

        # Retrieve the length limit; defaults to None if not provided
        length = argattrs.get("length")
        if length is None:
            continue

        # Ensure there is a value to compare
        value = argattrs.get("value")
        if value is None:
            continue

        # Perform the length check
        try:
            if len(value) > length:
                abort(
                    f"Argument {argname} has length {len(value)} "
                    f"which exceeds the allowed maximum of {length}"
                )
        except TypeError:
            abort(
                f"Argument {argname} has a value that does not support "
                "len() for length validation"
            )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Ensure we have a mapping of valid choices for each argument.
        if not hasattr(self, "choices"):
            # No choices defined; nothing to validate.
            return

        for arg_name, value in args.items():
            # Only validate arguments that have a predefined set of choices.
            if arg_name not in self.choices:
                continue

            valid_choices = self.choices[arg_name]

            # If the choice list is a mapping, use its keys as valid choices.
            if isinstance(valid_choices, dict):
                valid_choices = list(valid_choices.keys())

            if value not in valid_choices:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of {valid_choices!r}."
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: A mapping of argument names to dictionaries containing
                 ``value`` and optionally ``min`` and ``max``, or a list of
                 tuples in the form (value, min, max).
    """
    # support dict-based specification
    if isinstance(args, dict):
        for name, cfg in args.items():
            if not isinstance(cfg, dict):
                continue
            if 'value' not in cfg:
                continue
            val = cfg['value']
            min_val = cfg.get('min')
            max_val = cfg.get('max')
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument '{name}' with value {val} is less than minimum {min_val}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument '{name}' with value {val} is greater than maximum {max_val}"
                )
    # support list/tuple-based specification
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) >= 3:
                val, min_val, max_val = item[0], item[1], item[2]
                if min_val is not None and val < min_val:
                    raise ValueError(
                        f"Value {val} is less than minimum {min_val}"
                    )
                if max_val is not None and val > max_val:
                    raise ValueError(
                        f"Value {val} is greater than maximum {max_val}"
                    )
    else:
        raise TypeError(
            "args must be a dict or a list/tuple containing value-min-max tuples"
        )
    return args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        vars_dict = {}
    if not extra_vars:
        return vars_dict
    # Ensure extra_vars is iterable of dicts
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    for entry in extra_vars:
        if isinstance(entry, dict):
            vars_dict.update(entry)
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os, json
    # Try to locate a JSON spec file; fall back to YAML if JSON not found
    spec_file = None
    for name in ('plugin.json', 'spec.json', 'manifest.json'):
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_file = candidate
            break
    if spec_file is None:
        # Try YAML file
        try:
            import yaml
        except ImportError:
            raise FileNotFoundError("No plugin spec file found in '{}'".format(plugin_dir))
        for name in ('plugin.yaml', 'spec.yaml', 'manifest.yaml'):
            candidate = os.path.join(plugin_dir, name)
            if os.path.isfile(candidate):
                spec_file = candidate
                break
        if spec_file is None:
            raise FileNotFoundError("No plugin spec file found in '{}'".format(plugin_dir))
    # Load spec
    if spec_file.endswith('.json'):
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_dict = json.load(f)
    else:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_dict = yaml.safe_load(f)
    # Flatten dictionary
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items
    return _flatten(spec_dict)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if not os.getenv(env_var):
        os.environ[env_var] = str(self.config_path)
